<?php defined('ABSPATH') || exit; $filter = array_map(fn($v) => is_scalar($v) ? sanitize_text_field(wp_unslash($v)) : '', $_GET); $jobs = tj_jobs($filter); ?>
<section class="hero-search-section"><h1><?php tj_e('Tìm kiếm công việc mơ ước của bạn', 'Find your next IT opportunity'); ?></h1><p class="lead"><?php tj_e('Khám phá việc làm IT, nộp CV trực tuyến và tự tin hơn với trợ lý luyện phỏng vấn AI.', 'Explore IT jobs, apply online and build confidence with AI interview practice.'); ?></p><form class="hero-search-box-wrap" action="<?php echo esc_url(home_url('/viec-lam/')); ?>" method="get"><input type="hidden" name="lang" value="<?php echo esc_attr(tj_lang()); ?>"><div class="search-field-group"><span class="search-icon-lbl" aria-hidden="true">⌕</span><input aria-label="<?php tj_e('Từ khóa', 'Keywords'); ?>" name="q" value="<?php echo esc_attr($filter['q'] ?? ''); ?>" placeholder="<?php tj_e('Từ khóa, chức danh hoặc công ty…', 'Title, keyword or company…'); ?>"></div><div class="search-field-group"><?php tj_select('location', tj_t('Địa điểm', 'Location'), tj_term_options('location'), $filter['location'] ?? ''); ?></div><button class="search-btn-green"><?php tj_e('Tìm kiếm', 'Search jobs'); ?></button></form></section>
<?php if ($route === '') { ?><section class="tracking-card"><div class="tj-row tj-between"><div><h3><?php tj_e('Hành trình ứng tuyển của bạn', 'Your application journey'); ?></h3><p><?php tj_e('Theo dõi hồ sơ, nhận lịch phỏng vấn và chuẩn bị cho cơ hội tiếp theo.', 'Track applications, receive interview invitations and prepare for your next opportunity.'); ?></p></div><a class="tracking-btn" href="<?php echo esc_url(tj_url('tai-khoan/ung-tuyen')); ?>"><?php tj_e('Xem hồ sơ của tôi', 'My applications'); ?> →</a></div></section><?php } ?>
<div class="job-board-layout-container"><div class="job-board-grid"><aside class="filter-sidebar"><div class="filter-sidebar-header"><h3><?php tj_e('Bộ lọc tìm kiếm', 'Search filters'); ?></h3><a href="<?php echo esc_url(tj_url('viec-lam')); ?>"><?php tj_e('Xóa lọc', 'Clear'); ?></a></div><form method="get" action="<?php echo esc_url(home_url('/viec-lam/')); ?>" class="tj-stack"><?php tj_hidden('lang', tj_lang()); tj_hidden('q', $filter['q'] ?? ''); foreach (['skill' => tj_t('Kỹ năng', 'Skill'), 'category' => tj_t('Nhóm nghề', 'Category'), 'location' => tj_t('Địa điểm', 'Location')] as $tax => $label) { tj_select($tax, $label, tj_term_options($tax), $filter[$tax] ?? ''); } tj_select('job_type', tj_t('Loại hình', 'Job type'), ['' => tj_t('Tất cả', 'All'), 'full-time' => tj_t('Toàn thời gian', 'Full-time'), 'part-time' => tj_t('Bán thời gian', 'Part-time'), 'internship' => tj_t('Thực tập', 'Internship'), 'remote' => 'Remote'], $filter['job_type'] ?? ''); tj_input('min_salary', tj_t('Lương từ (VND/tháng)', 'Minimum (VND/month)'), $filter['min_salary'] ?? '', 'number'); tj_input('max_salary', tj_t('Đến (VND/tháng)', 'Maximum (VND/month)'), $filter['max_salary'] ?? '', 'number'); tj_button('Áp dụng bộ lọc', 'Apply filters'); ?></form></aside><section class="jobs-list-column"><div class="jobs-list-header"><h2><?php echo esc_html(tj_t('Cơ hội việc làm IT', 'IT job opportunities')); ?></h2><span class="tj-muted"><?php echo esc_html($jobs['total']); ?> <?php tj_e('vị trí tuyển dụng', 'open positions'); ?></span></div><div class="tj-stack"><?php if (!$jobs['posts']) { tj_empty(tj_t('Không có việc làm phù hợp. Hãy thử bộ lọc khác.', 'No matching jobs. Try other filters.')); } foreach ($jobs['posts'] as $job) { tj_job_card($job); } ?></div><?php tj_pagination((int)$jobs['pages']); ?></section></div></div>
<?php if ($route === '') { ?><section class="tj-container"><div class="tj-page-heading"><h2><?php tj_e('Công ty tuyển dụng hàng đầu', 'Featured companies'); ?></h2><a href="<?php echo esc_url(tj_url('cong-ty')); ?>"><?php tj_e('Xem tất cả', 'View all'); ?> →</a></div><div class="tj-company-grid"><?php foreach (get_posts(['post_type' => 'tj_company', 'numberposts' => 6, 'meta_key' => 'tj_featured', 'meta_value' => '1']) as $company) { ?><a class="tj-panel" href="<?php echo esc_url(tj_url('cong-ty', ['company' => $company->ID])); ?>"><span class="tj-company-mark"><?php echo esc_html(mb_substr(tj_title($company->ID), 0, 1)); ?></span><h3><?php echo esc_html(tj_title($company->ID)); ?></h3><p class="tj-muted"><?php echo esc_html(tj_meta($company->ID, 'location')); ?></p></a><?php } ?></div></section><?php } ?>
